head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > sortEvent]<br/>sortable=true 일때 Header Column 에서 정렬을 실행할 이벤트의 종류를 설정합니다.",
    "validation" : [
        "accessibility=true 또는 sortHeaderDiv=true 이면 항상 'onclick' 으로 동작합니다.",
        "'onclick' 설정 시 Header Column 을 클릭 시 정렬을 실행합니다.",
        "'ondblclick'(기본값) 설정 시 Header Column 을 더블 클릭 시 정렬을 실행합니다.",
        "sortEvent 속성값에 'onclick', 'ondblclick' 외의 값을 설정하면 정렬이 실행되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 읽기 (미설정 '' / 'onclick' / 'ondblclick' / 'onmouseover'(잘못된값) / 'true' / 'false')
    let sortEventVal = con_sortEvent.getValue();
    let accessibilityVal = con_accessibility.getValue();
    let sortHeaderDivVal = con_sortHeaderDiv.getValue();

    // 현재 설정/동작 라벨 생성 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="Header Column 을 클릭/더블클릭하면 데이터가 정렬됩니다. (sortable=true, showSortableImage=true 고정) / 초기 표시순서: Cherry, Apple, Date, Banana"', '', 'label1');
    $c.gcm.createLabel('label="현재 설정: sortEvent=' + (sortEventVal === '' ? '미설정(기본 ondblclick)' : sortEventVal) + ' / accessibility=' + (accessibilityVal === '' ? '미설정(기본 false)' : accessibilityVal) + ' / sortHeaderDiv=' + (sortHeaderDivVal === '' ? '미설정(기본 false)' : sortHeaderDivVal) + '"', '', 'label2');

    // dataList 직접 생성 (4행, 빈 행 0 / 정렬 시 순서가 눈에 띄게 바뀌도록 col1 값 구성)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    let nameArr = ['Cherry', 'Apple', 'Date', 'Banana'];
    let descArr = ['체리', '사과', '대추', '바나나'];
    for (let r = 0; r < 4; r++) {
        strDl += '<w2:row>';
        strDl += '<col1>' + nameArr[r] + '</col1>';
        strDl += '<col2>' + descArr[r] + '</col2>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // sortEvent / accessibility / sortHeaderDiv 속성 (미설정 시 속성 미부여 = 기본값)
    let sortEventAttr = sortEventVal === '' ? '' : 'sortEvent="' + sortEventVal + '" ';
    let accessibilityAttr = accessibilityVal === '' ? '' : 'accessibility="' + accessibilityVal + '" ';
    let sortHeaderDivAttr = sortHeaderDivVal === '' ? '' : 'sortHeaderDiv="' + sortHeaderDivVal + '" ';

    // target 생성 : sortable=true / showSortableImage=true 고정, sortEvent 등 조건 적용
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + sortEventAttr + accessibilityAttr + sortHeaderDivAttr + 'sortable="true" showSortableImage="true" dataList="data:dlt_bind" checkAllType="false" id="" ev:onsort="scwin.target1_onsort" style="width:420px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="column2" value="desc"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" inputType="text" dataType="text" id="col1"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" dataType="text" id="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 정렬 실행(onsort) 시 자동 출력 : 정렬이 실행된 컬럼/방향 + 정렬 후 name 컬럼 표시순서
//  (헤더 클릭/더블클릭은 사용자 액션으로 수행 → 정렬 트리거 버튼은 생성하지 않음)
//  onsort 는 sortable 적용 헤더에서 클릭/더블클릭으로 정렬방식이 변경되었을 때만 발생하므로,
//  발생 자체가 '정렬 실행됨'의 신호이다.
scwin.target1_onsort = function () {
    // 정렬 후 화면에 보이는 name(col1) 컬럼 데이터를 표시순서대로 수집
    //  td.textContent 로 읽으면 accessibility=true 모드에서 셀이 항상 embeddedInput(INPUT/SELECT)
    //  으로 렌더되어 텍스트 노드가 비어 표시순서가 ""로 나옴.
    //  → 그리드 공개 API getCellDisplayData(표시행인덱스, 컬럼ID) 로 셀 표시값을 읽어
    //    일반/accessibility 모드 모두에서 정확한 표시순서를 얻는다.
    let order = [];
    let rowCnt = target1.getRowCount();
    for (let i = 0; i < rowCnt; i++) {
        let v = target1.getCellDisplayData(i, "col1");
        v = (v == null ? "" : ("" + v)).trim();
        if (v === "") {
            // 혹시 표시데이터가 비면 셀 내부 input/select value 로 fallback
            let cellTd = document.querySelector("[id*='target1'] td[id$='_cell_" + i + "_0'], [id*='target1'] td[id*='_cell_'][id$='_" + i + "_0']");
            if (cellTd) {
                let inp = cellTd.querySelector("input, select");
                if (inp) {
                    v = (inp.value || "").trim();
                }
            }
        }
        if (v !== "") {
            order.push(v);
        }
    }

    // 현재 정렬 방향 : name 헤더 th 의 aria-sort 로 판별 (ascending/descending)
    let dir = "";
    let headTable = document.querySelector("[id*='target1_head_table']");
    if (headTable) {
        let th = headTable.querySelector("th[aria-sort='ascending'], th[aria-sort='descending']");
        if (th) {
            dir = th.getAttribute("aria-sort") === "ascending" ? "오름차순" : "내림차순";
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("[정렬 실행] 컬럼=name / 방향=" + (dir || "(미상)") + " / 표시순서=" + order.join(", "));
};
